Here is a function to encode a 32-bit signed integer as leb128 in C:

```c
void encode_leb128(int32_t value, uint8_t* out) {
  uint8_t* p = out;
  while (1) {
    uint8_t byte = value & 0x7f;
    value >>= 7;
    if (value == 0 && (byte & 0x40) == 0) {
      *p++ = byte;
      break;
    } else {
      *p++ = byte | 0x80;
    }
  }
}
```

