fn gitbasename(path: &str) -> &str {
    let mut base = path;

    if path.is_empty() {
        return ".";
    }

    while !is_separator(base.char_at(0)) {
        base = &base[1..];
    }

    let mut i = 0;
    while is_separator(base.char_at(i)) {
        i += 1;
    }
    if base.char_at(i) {
        let mut j = i + 1;
        while j < base.len() && is_separator(base.char_at(j)) {
            j += 1;
        }
        let mut result = String::from_str(base.slice(..j));
        while j < base.len() && !is_separator(base.char_at(j)) {
            result.push(base.char_at(j));
            j += 1;
        }
        result.truncate(result.len() - 1);
        base = result.as_str();
    }

    base
}
