Here's a simple sorting algorithm implemented in C++:

```c++
#include <iostream>
#include <algorithm>

using namespace std;

void sort_ascending(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] > arr[j]) {
                swap(arr[i], arr[j]);
            }
        }
    }
}

int main() {
    int arr[] = {72, 27, 14, 55, 27, 14, 55, 27, 14};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Unsorted array: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    sort_ascending(arr, n);

    cout << "Sorted array: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

In this implementation, we use the `sort_ascending` function to sort the array in ascending order. The function takes an array and its size as arguments, and uses nested loops to compare and swap adjacent elements if they are in the wrong order. In the `main` function, we first print the unsorted array, then call the `sort_ascending` function to sort it, and finally print the sorted array.

A sparse matrix is a matrix where many of the elements are zero or don't need to be stored. This can lead to significant space savings and faster operations. Here's an example of a sparse matrix class in C++:

```cpp
#include <iostream>
#include <vector>

using namespace std;

class SparseMatrix {
private:
    vector<vector<double>> data;
    int rows, cols;

    // Function to calculate the row indices for a given
    // non-zero element in the matrix
    int get_row_index(int row, int col) {
        return row * cols + col;
    }

public:
    SparseMatrix(int rows, int cols) {
        this->rows = rows;
        this->cols = cols;
        data.resize(rows, vector<vector<double>>());
    }

    // Function to add a non-zero element to the matrix
    void add_element(int row, int col, double value) {
        if (data[row][col] == 0) {
            data[row][col] = value;
        }
    }

    // Function to access the value of a non-zero element in the matrix
    double get_value(int row, int col) {
        return data[get_row_index(row, col)];
