public class EURionWatermarking {
    public static void main(String[] args) throws IOException {
        // Load the original image
        ImageFrame original = ImageFrameReader.read("input.jpg");

        // Convert the image to grayscale
        IplImage gray = IplImage.create(original.width(), original.height(), IPL_DEPTH_8U, 1);
        Imgproc.cvtColor(original, gray, Imgproc.COLOR_BGR2GRAY);

        // Detect the EURion constellation
        int[][] bb = Imgproc.findContours(gray, new int[] { 10, 10, 200 }, new int[] { 2, 2, 2 }, Imgproc.RETR_LIST, Imgproc.CHAIN_APPROX_SIMPLE);

        // Draw the constellation onto the original image
        drawConstellation(gray, bb, 20);

        // Save the watermarked image
        ImageFrame watermarked = ImageFrameWriter.write(new BufferedImage(gray.width(), gray.height(), gray.depth()), "output.jpg");

        // Display the result
        System.out.println("Watermarked image saved to output.jpg");
    }

    private static void drawConstellation(IplImage image, int[][] bb, int radius) {
        for (int i = 0; i < bb.length; i++) {
            int[] contour = bb[i];
            drawContour(image, contour, radius, new Point(contour[0][0], contour[0][1]), false);
        }
    }

    private static void drawContour(IplImage image, int[][] contour, int radius, Point center, boolean filled) {
        if (radius < 3) {
            return;
        }

        int[] perimeter = new int[contour.length];
        for (int i = 0; i < contour.length; i++) {
            int[] point = contour[i];
            int x = (int) (center.x + point[0] * radius);
            int y = (int) (center.y + point[1] * radius);
            if (filled) {
                image.setPixel(x, y, filled);
            } else {
                image.and(x, y);
            }
            perimeter[i] = x;
        }

        int[][] newContour = new int[perimeter.length][2];
        for (int i = 0; i < perimeter.length; i++) {
            newContour[i][0] = (int) (center.x + perimeter[i] * radius) * 255;
            newContour[i][1] = (int) (center.y + perimeter[i + 1] * radius) * 255;
        }

        drawContour(image, newContour, radius - 1, center, filled);
    }
}
