Here's an example Arduino program that runs a single cylinder engine using an analogRead function for the O2 sensor, an analogWrite function to inject more fuel, and sets up the system for idling the engine at 500 RPM. The RPM sensor is a PWM sensor and is read using the pulseIn function.
```C++
// Define the pins for the O2 sensor and fuel injector
const int o2SensorPin = A0; // Analog pin for O2 sensor
const int fuelInjectorPin = 9; // Digital pin for fuel injector

// Define the pins for the RPM sensor
const int rpmPin = 2; // PWM pin for RPM sensor

// Define the threshold for the O2 sensor
const int o2SensorThreshold = 1.5; // 1.5V corresponds to optimal engine burn

void setup() {
  // Setup the serial communication
  Serial.begin(9600);

  // Setup the RPM sensor
  pinMode(rpmPin, INPUT);
  analogWrite(rpmPin, 0);  // Set the RPM to 0

  // Setup the O2 sensor
  pinMode(o2SensorPin, INPUT);

  // Set the initial fuel injection
  analogWrite(fuelInjectorPin, 0);
}

void loop() {
  // Read the O2 sensor
  int o2SensorValue = analogRead(o2SensorPin);

  // Calculate the RPM
  int rpm = pulseIn(rpmPin, HIGH) * 20 / 255;  // Assuming 255 PWM pulses per revolution

  // Determine if the engine is idling
  if (rpm == 0) {
    Serial.println("Engine is idling.");
    analogWrite(fuelInjectorPin, 0);  // No fuel injection
  } else {
    // Calculate the fuel injection
    int fuelInjectionValue = map(o2SensorValue, 0, o2SensorThreshold, 0, 255);
    analogWrite(fuelInjectorPin, fuelInjectionValue);

    // Adjust the RPM to maintain 500 RPM
    int rpmDelta = (500 - rpm) * 20 / 255;
    analogWrite(rpmPin, rpmDelta);

    Serial.print("Fuel injection: ");
    Serial.print(fuelInjectionValue);
    Serial.print("msb); RPM: ");
    Serial.print(rpm);
    Serial.println("RPM.");
  }
}
```
Note: This program is just an example and may not work as-is without proper calibration and adjustment for your specific engine and sensors.

