    for root, dirs, files in os.walk(source_folder):
        for file in files:
            if file.endswith(".npy"):
                src_path = os.path.join(root, file)
                dst_path = os.path.join(target_folder, f"{os.path.splitext(file)[0]}_{os.path.splitext(file)[1]}")
