  constructor() {
    this.roots = [];
  }

  insert(val) {
    let leftSubtree = new TreeNode(val, this.roots[0], this.roots[1]);
    this.roots[0].left = leftSubtree;
    this.roots[1].right = leftSubtree;

    let rightSubtree = new TreeNode(val, this.roots[0], this.roots[2]);
    this.roots[0].right = rightSubtree;
    this.roots[1].left = rightSubtree;

    this.addNode(val);
  }

  remove(val) {
    let current = this.roots[0];
    let left = current.left;
    let right = current.right;

    while (left && right) {
      if (left.val == val) {
        left.left = current.right;
        current.right = left;
        current = left;
      } else if (right.val == val) {
        right.left = current.left;
        current.left = right;
        current = right;
      } else {
        current = current.left;
      }
    }
    if (left) this.removeNode(left);
    if (right) this.removeNode(right);
  }

  addNode(val) {
    let current = this.roots[0];
    let left = current.left;
    let right = current.right;

    if (val < this.val(current.val)) {
      val = this.val(current.val);
      current = new TreeNode(val, left, right);
    }

    left.left = current.right;
    current.right = left;

    this.roots.push(current);
  }

  val(val) {
    return this.val(val);
  }
}
```
