            if (addressTypes.isEmpty()) {
                throw new DomainException(INVALID_PARAMETER_TYPE.getCode(), "No address types found");
            }
            type = getMostFrequentType(addressTypes);
        }

        if (enrichmentInfo.hasEnrichedBy(STANDARD, TYPES) && hasEnoughTypes(addressTypes)) {
            type = getMostFrequentType(addressTypes);
        }
    }

    private void validate(List<AddressExtraInfo> addressExtraInfos) {
        if (addressExtraInfos == null) {
            throw new DomainException(
                    INVALID_PARAMETER_TYPE.getCode(), "AddressExtraInfo must be instanced");
        }
    }

    private AddressType getMostFrequentType(Set<AddressType> addressTypes) {
        Map<AddressType, Integer> typeCounts = new HashMap<>();

        for (AddressType type : addressTypes) {
            typeCounts.put(type, typeCounts.getOrDefault(type, 0) + 1);
        }

        for (Map.Entry<AddressType, Integer> entry : typeCounts.entrySet()) {
            if (entry.getValue() >= QUANTITY_REQUIRED) {
                return entry.getKey();
