void PID_Calculate(float Input, float Output, float &Error, float &Integral)
{
    // Calculate the PID error and integral
    Error = Input - PID_Input;
    Integral += Error;

    // Calculate the PID output
    PID_Output = PID_Input + PID_Kp * Error + PID_Ki * Integral + PID_Kd * Error * Integral;

    // Limit the output to the valid range
    if (PID_Output > PID_TARGET_VALUE) {
        PID_Output = PID_TARGET_VALUE;
    } else if (PID_Output < 0) {
        PID_Output = 0;
    }
}

