JavaScript:

```js
const handle = document.querySelector('.slider-handle');
const circle = document.querySelector('.slider-circle');

handle.addEventListener('mousedown', e => {

  let originX = e.clientX;

  document.addEventListener('mousemove', moveHandler);

  function moveHandler(e) {
    let diffX = e.clientX - originX;
    let newRadius = Math.max(0, Math.min(100, 50 + diffX));

    circle.style.width = newRadius * 2 + 'px';
    circle.style.height = newRadius * 2 + 'px';

    originX = e.clientX;
  }

  document.addEventListener('mouseup', () => {
    document.removeEventListener('mousemove', moveHandler);
  });

});
```

This creates a draggable handle that adjusts the radius of the inner circle. You can add concentric circles and other styling as needed.

