const draggable2 = document.querySelector('#draggable2')

draggable1.addEventListener('dragstart', (e) => {
  // dataTransfer принадлежит draggable1 
})

draggable2.addEventListener('dragover', (e) => {
  // dataTransfer принадлежит draggable2, отличается от предыдущего
})  
</script>
```

