Here's an example of how you could define a linked list data type and implement a function to reverse a linked list in C:
```c
#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int data;
    struct node *next;
} Node;

Node *head = NULL;

void printList(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("%d ", current->data);
        current = current->next;
    }
    printf("\n");
}

void reverseList(Node *head) {
    Node *temp = head->next;
    head->next = NULL;
    head = temp;
    reverseList(temp);
}

int main() {
    Node *newNode = malloc(sizeof(Node));
    newNode->data = 10;
    newNode->next = NULL;
    head = newNode;
    printList(head);
    reverseList(head);
    printList(head);
    return 0;
}
```
