function bubbleSort(&$NAME_1, $n = 1) {
    $swapped = true;

    while ($swapped) {
        $swapped = false;

        for ($i = 0; $i < $n - 1; $i++) {
            $swapped = true;

            for ($j = 0; $j < $n - $i - 1; $j++) {
                if ($NAME_1[$j] > $NAME_1[$j + 1]) {
                    $temp = $NAME_1[$j];
                    $NAME_1[$j] = $NAME_1[$j + 1];
                    $NAME_1[$j + 1] = $temp;
                    $swapped = false;
                }
            }
        }
    }
}

