  cout << board[x][y] << endl;
  currentPlayer = (currentPlayer == 1) ? 2 : 1;
}

int main() {
  board.resize(3); // initialize the board
  for (int i = 0; i < board[0].size(); i++) {
    board[0][i] = 'X';
    board[1][i] = 'O';
    board[2][i] = '.';
  }

  while (true) {
    drawBoard();
    cout << "Player 1 (X), enter row and column (e.g. 2 4): ";
