        {
            spawner.nextSpawn = Time.time;
        }
    }
}

public class GridSpawnManager : MonoBehaviour
{
    public Transform[] gridTransforms;
    private float nextSpawn = 0f;
    private int nextPosition = 0;

    private void Update()
    {
        foreach (Transform child in gridTransforms)
        {
            if (child.CompareTag("Unit"))
            {
                if (Time.time > nextSpawn)
                {
                    SpawnUnit();
                    nextSpawn = Time.time + spawnRate;
                    nextPosition++;
                    if (nextPosition >= gridTransforms.Length)
                    {
                        nextPosition = 0;
                    }
