function solve(s) {
    // Calculate the parity bit
    var parity = parseInt(s[0]);
    var rest = s.slice(1);
    while (rest.length > 0 && parseInt(rest[0]) === parity) {
        rest = rest.slice(1);
    }

    // Find the error bit
    var error_index = 0;
    for (var i = 0; i < rest.length; i++) {
        var parity_left = parseInt(rest.slice(0, i));
        var error = parseInt(rest[i]) ^ parity_left;
        if (error === 1) {
            error_index = i + 1;
            break;
        }
    }

    // Correct the error bit
    var error_str = error.toString();
    if (error_str[0] === '0') {
        correction = rest.slice(0, error_index).reduce(function(acc, val, idx) {
            acc = (acc << 1) + (val & 1);
            return acc & Math.pow(2, idx);
        }, 1);
    } else {
        correction = rest.slice(error_index).reduce(function(acc, val, idx) {
            acc = (acc << 1) + (val & 1);
            return acc & Math.pow(2, idx);
        }, 1);
    }

    // Extract the decimal value
    var decimal = correction.toString(2).slice(0, -1);
    return decimal;
}

