```cpp
#include <iostream>

void quicksort(int arr[], int n) {
    if (n <= 1) {
        return;
    }

    int mid = (n / 2);
    quicksort(arr, mid);
    quicksort(arr, n - mid);

    // merge the two sorted subarrays
    int l = 0, r = mid - 1;
    int pivot = arr[mid];
    while (l < r) {
        if (arr[l] < pivot) {
            std::swap(arr[l], arr[r]);
            l++;
        } else if (arr[r] > pivot) {
            std::swap(arr[r], arr[l]);
            r--;
        } else {
            l++;
            r--;
        }
    }

    std::swap(arr[mid], arr[l]);
    quicksort(arr, l);
    quicksort(arr, r + 1);
}

int main() {
    int arr[] = {5, 1, 4, 3, 2};
    int n = sizeof(arr) / sizeof(arr[0]);
    quicksort(arr, n);
    for (int i = 0; i < n; i++) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;
}
```

