Sure! Here's a basic merge sort implementation in C++:

```cpp
#include <iostream>
#include <vector>

using namespace std;

void mergeSort(vector<int>& arr, int left, int right) {
    if (left >= right) {
        return;
    }

    int mid = (left + right) / 2;

    vector<int> temp(mid - left + 1);

    // Partition the left and right subarrays
    mergeSort(arr, left, mid);
    mergeSort(arr, mid + 1, right);

    // Merge the two subarrays
    int i = left;
    int j = mid + 1;
    int k = 0;

    while (i <= mid && j <= right) {
        if (arr[i] < arr[j]) {
            temp[k] = arr[i];
            i++;
        } else {
            temp[k] = arr[j];
            j++;
        }
        k++;
    }

    while (i <= mid) {
        temp[k] = arr[i];
        i++;
        k++;
    }

    while (j <= right) {
        temp[k] = arr[j];
        j++;
        k++;
    }

    // Copy the merged subarray back to the original array
    for (k = 0; k < temp.size(); k++) {
        arr[left + k] = temp[k];
    }
}

int main() {
    vector<int> arr = {5, 4, 3, 2, 1};
    mergeSort(arr, 0, 4);
    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

