public static void AnglesToVectors(Vector3 refForward, Vector3 refUp, float angleH, float angleV, out Vector3 forwardVector, out Vector3 upVector)
{
    float cA = Mathf.Cos(angleV);
    float sA = Mathf.Sin(angleV);
    float cL = Mathf.Cos(angleH);
    float sL = Mathf.Sin(angleH);

    float x = cA * cL;
    float y = cA * sL;
    float z = sA;

    forwardVector = new Vector3(x, y, z);
    upVector = Vector3.Cross(refUp, refForward);
}
