public static bool AnyDuplicates(int[] nums)
{
    // Check for duplicates using a hash set
    if (nums.Length < 2) return false;
    HashSet<int> set = new HashSet<int>();
    foreach (int n in nums)
    {
        if (set.Contains(n)) return true;
        set.Add(n);
    }
    return false;
}
