function goToLocation(startPosition, targetPosition) {
  const steps = [];
  let currentStep = 'east';
  let direction = 'east';
  let distance = 20; // distance between steps

  while (currentStep!== 'west' && distance > 0) {
    // move in the given direction for a certain distance
    steps.push(currentStep);
    currentStep += direction;
    distance--;

    // if walking towards the target position is finished, change direction
    if (currentStep === 'east' && distance === 0) {
      direction = 'west';
    }
  }

  // if walking towards the target position is finished, change direction
  if (currentStep === 'west' && distance === 0) {
    direction = 'east';
  }

  // return the sequence of steps
  return steps.join(' ');
}
