// Function to calculate the sum of lots for the specified symbol and time period
double LotsHistogram(const char* symbol, int period, int from, int to, int offset, int limit, bool isHistogram)
{
    const int nLots = 1000;
    int lots[nLots];
    double sum = 0.0;

    // Get the data for the specified symbol and time period
    const int dataCount = TickValueCount(symbol, from, to, offset, limit);
    const double* data = AllocReducedMemory(dataCount * sizeof(double));
    TickValueEnumerator e(symbol, from, to, offset, limit, data, dataCount);

    // Loop through the data and sum the lots
    while (e.MoveNext())
    {
        int lot = e.GetLot();
        if (lot < 0 || lot >= nLots)
            continue;
        lots[lot]++;
        sum += e.GetTick();
    }

    // Calculate the sum of lots
    for (int i = 0; i < nLots; i++)
        sum += lots[i] * e.GetTick();

    // Check if the specified time period is a multiple of the lot size
    int step = period / (double)(nLots);
    if (step != 1.0)
    {
        int remainder = period % (double)(nLots);
        if (remainder != 0)
            step = step * (double)(nLots) / remainder;
    }

    // Calculate the sum of lots and return it as a histogram
    if (isHistogram)
    {
        int sumLots = sum / step;
        int hist[sumLots];
        for (int i = 0; i < sumLots; i++)
            hist[i] = i * step;
        return sum;
    }
    else
    {
        return sum;
    }
}
