```sql
DECLARE
  last_name VARCHAR(20);
  department VARCHAR(20);
  salary DECIMAL(5, 2);
BEGIN
  OPEN employees_cursor FOR
    SELECT last_name, department, salary
    FROM employees
    ORDER BY salary DESC
    LIMIT 4;

  LOOP
    FETCH employees_cursor INTO last_name, department, salary;

    IF last_name = '' OR department = '' OR salary = '' THEN
      DBMS_OUTPUT.PUT_LINE('No data');
    ELSIF
      DBMS_OUTPUT.PUT_LINE('Error: unspecified:' || sqlcode);
    END IF;

    CLOSE employees_cursor;
  END LOOP;

  CLOSE employees_cursor;
END;

```

