Here's a simple implementation of a single producer single consumer queue with atomic operations in C++ using the `std::queue` container from the C++11 standard library:
```c
#include <iostream>
#include <queue>
#include <atomic>
#include <thread>

const int MAX_ITEMS = 10;  // Maximum number of items in the queue

// A simple item that can be added to the queue
struct Item {
    int value;
    std::atomic<bool> consumed;
};

// The queue class
class Queue {
public:
    Queue() : front_(0), rear_(0), items_(MAX_ITEMS) {}

    // Enqueues an item
    void enqueue(int value) {
        std::atomic_fetch_add(&rear_, 1);
        if (rear_ == MAX_ITEMS) {
            std::cout << "Queue is full" << std::endl;
            return;
        }
        items_[rear_] = value;
    }

    // Dequeues an item
    int dequeue() {
        if (front_ == rear_) {
            std::cout << "Queue is empty" << std::endl;
            return -1;
        }
        std::atomic_fetch_add(&front_, 1);
        return items_[front_];
    }

    // Consumes an item
    void consume(int value) {
        auto it = std::find_if(items_.begin(), items_.end(),
            [value](const Item& item) { return item.value == value; });
        if (it != items_.end()) {
            std::cout << "Consumed item: " << value << std::endl;
            it->consumed = true;
        } else {
            std::cout << "Item not found" << std::endl;
        }
    }

private:
    int front_;  // Index of the front item
    int rear_;   // Index of the rear item
    Item items_[MAX_ITEMS];  // Array of items in the queue
};

// The producer thread
void producer() {
    for (int i = 0; i < MAX_ITEMS; i++) {
        for (int j = 0; j < 10; j++) {
            std::cout << "Producer: " << i << std::endl;
            queue.enqueue(i);
            std::cout << "Producer: " << i << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
}

// The consumer thread
void consumer() {
    while (true) {
        int value;
        if (queue.dequeue(value)) {
            std::cout << "Consumer: " << value << std::endl;
            queue.consume(value);
        } else {
            std::cout << "Consumer: Queue is empty" << std::endl;
        }
    }
}

int main() {
    Queue queue;
    std::thread producer_thread(producer);
    std::thread consumer_thread(consumer);
    producer_thread.join();
    consumer_thread.join();
    return 0;
}
```
