            arr.swap(n - 1, n);
        }

        // Partition the rest of the array to the left and right of the pivot
        let mut left = 0;
        let mut right = n - 1;
        while left < right {
            if arr[left] < pivot {
                arr.swap(left, right);
                left += 1;
            } else if arr[right] > pivot {
                arr.swap(left, right);
                right -= 1;
            }
        }

        // Move the pivot to the right partition
        arr[n - 1] = arr[right];
        n -= 1;
    }

    arr
}
```

This implementation uses a simple iterative approach to sort the input array. It first calculates the middle element of the array (the "pivot") and then partitions the array to the left and right of the pivot based on whether the current element is smaller or larger than the pivot. It then swaps the pivot to the right partition if necessary and repeats the process until the array is fully sorted.

Note that this implementation assumes that the input array is already sorted in ascending order. If the input array is not already sorted, you may need to add additional logic to handle unsorted input.

