    .setName('remove-role')
    .setDescription('Remove a role from a member when they add a reaction')
    .addIntegerOption((option) => {
        option.setName('role_id');
        option.setDescription('The ID of the role to remove');
    })
    .addIntegerOption((option) => {
        option.setName('message_id');
        option.setDescription('The ID of the message to watch for reactions');
    })
    .addIntegerOption((option) => {
        option.setName('member_id');
        option.setDescription('The ID of the member to remove the role from');
    })
    .addIntegerOption((option) => {
        option.setName('channel_id');
        option.setDescription('The ID of the channel to remove the role from');
    })
    .setGuild(server)
    .build();

const removeRole = (guild, messageId, memberId, channelId, roleId) => {
