Here's a JavaScript function that will return the first or second half of workdays in a month:

```js
function getWorkdayRange(month, year, half) {
  let startDate, endDate;
  let firstDay = new Date(year, month - 1, 1);
  let lastDay = new Date(year, month, 0);
  let totalDays = lastDay.getDate();

  if (half === 'first') {
    startDate = getNextWorkday(firstDay);
    endDate = getWorkday(firstDay, Math.ceil(totalDays / 2));
  } else {
    startDate = getWorkday(firstDay, Math.ceil(totalDays / 2) + 1);
    endDate = getPreviousWorkday(lastDay);
  }

  return [startDate.toISOString().split('T')[0], endDate.toISOString().split('T')[0]];
}

function getNextWorkday(date) {
  let day = date.getDay();
  if (day === 6) day = 0;  // Sunday -> 0
  return new Date(date.setDate(date.getDate() + (1 + (day >= 1 && day <= 5 ? 0 : 7))));
}

function getPreviousWorkday(date) {
  let day = date.getDay();
  if (day === 0) day = 6;  // Sunday -> 6
  return new Date(date.setDate(date.getDate() - (1 + (day >= 1 && day <= 5 ? 0 : 7)))); 
}

function getWorkday(start, offset) {
  let date = new Date(start);
  for (let i = 0; i < offset; i++) {
    date = getNextWorkday(date);
  }
  return date;
}
```

You can call the function like this:
```js
getWorkdayRange(7, 2023, 'first');
// Returns ['2023-07-03', '2023-07-14']

getWorkdayRange(7, 2023, 'second'); 
// Returns ['2023-07-17', '2023-07-31']
```

