```javascript
import { useState, useEffect } from'react';

function useStatePersist(key) {
  const [state, setState] = useState({});

  useEffect(() => {
    const persistState = (newState) => {
      localStorage.setItem(`${key}:${JSON.stringify(newState)}`, JSON.stringify(state));
    };

    persistState(newState);

    return () => {
      const restoredState = localStorage.getItem(`${key}:${JSON.stringify(newState)}`);
      if (restoredState) {
        setState(JSON.parse(restoredState));
      }
    };
