  return [state, setState];
}

function persistState(key, newState) {
  localStorage.setItem(`${key}:${JSON.stringify(newState)}`, JSON.stringify(newState));
}

function restoreState(key, previousState) {
  const restoredState = localStorage.getItem(`${key}:${JSON.stringify(previousState)}`);
  if (restoredState) {
    return JSON.parse(restoredState);
  }
  return previousState;
}
