func getCoordinatesBetween(x1, y1, x2, y2 int) [][]int {
    var coordinates [][]int
    for x := x1; x <= x2; x++ {
        for y := y1; y <= y2; y++ {
            coordinates = append(coordinates, []int{x, y})
        }
    }
    return coordinates
}
