  static uint32_t magic = 2189222522ULL;
  uint32_t x = (magic * seed[0]) & 0xffffffff;
  seed[0] = (seed[0] + x) & 0xffffffff;
  seed[1] = (seed[1] + x) & 0xffffffff;
  return x;
}

