double EllipsePolygonIntersection(Ellipse ellipse, Polygon polygon)
{
    double intersectArea = 0;
    List<Point> ellipsePoints = ellipse.GetPoints();
    List<Point> polyPoints = polygon.GetPoints();

    for (int i = 0; i < polyPoints.Count; i++)
    {
        Point p1 = polyPoints[i];
        Point p2 = polyPoints[(i + 1) % polyPoints.Count];

        if (ellipse.Contains(p1))
        {
            intersectArea += ellipse.Area(p1, p2);
        }
        else if (ellipse.Contains(p2))
        {
            intersectArea += ellipse.Area(p2, p1); 
        }
        else
        {
            Point intersect1, intersect2;
            if (ellipse.Intersects(p1, p2, out intersect1, out intersect2))
            {
                intersectArea += ellipse.Area(intersect1, intersect2); 
            }
        }
    }

    return intersectArea;
}
