```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_TOKEN_LENGTH 100

void tokenize(char *input, char ***tokens, int *num_tokens) {
    int i = 0, j = 0, k = 0;
    char c;
    *tokens = malloc(MAX_TOKEN_LENGTH * sizeof(char *));
    *num_tokens = 0;

    while (1) {
        c = input[i];
        if (c == '\n') {
            (*tokens)[(*num_tokens)++] = malloc(j + 1);
            strncpy((*tokens)[(*num_tokens) - 1], input + j, i - j);
            (*tokens)[(*num_tokens) - 1][i - j] = '\0';
            j = 0;
        } else if (isspace(c)) {
            continue;
        } else {
            j++;
        }
        if (c == '\0') {
            break;
        }
        i++;
    }
}

int main() {
    char input[] = "Hello, world! This is a test.";
    char ***tokens;
    int num_tokens;
    tokenize(input, &tokens, &num_tokens);

    for (int i = 0; i < *num_tokens; i++) {
        printf("Token %d: %s\n", i + 1, tokens[i]);
    }

    free(tokens);
    return 0;
}
```
