Here is a C# program that prints the Mandelbrot set:
```csharp
using System;
using System.Drawing;

namespace MandelbrotSet
{
    class Program
    {
        static void Main(string[] args)
        {
            int width = 80;
            int height = 25;
            int iterations = 100;
            double zoom = 2;
            double moveX = -0.5;
            double moveY = 0;

            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    double cX = (x - width / 2) * zoom / width + moveX;
                    double cY = (y - height / 2) * zoom / height + moveY;
                    double zX = 0;
                    double zY = 0;
                    int iteration = 0;
                    while (zX * zX + zY * zY < 4 && iteration < iterations)
                    {
                        double newX = zX * zX - zY * zY + cX;
                        double newY = 2 * zX * zY + cY;
                        zX = newX;
                        zY = newY;
                        iteration++;
                    }
                    if (iteration == iterations)
                        Console.Write(" ");
                    else
                        Console.Write("*");
                }
                Console.WriteLine();
            }
            Console.ReadKey();
        }
    }
}
```

This program:

- Defines the width, height, iterations, zoom level, and position of the viewport
- Loops through each pixel in the viewport 
- For each pixel, iterates the Mandelbrot calculation to see if the point diverges 
- If it diverges, prints a * for that pixel, otherwise prints a space
- The end result prints the Mandelbrot set to the console window

