Here is a C++ class using SFML to represent a sprite sheet:
```cpp
#include <SFML/Graphics.hpp>

class SpriteSheet {
public:
    SpriteSheet(sf::Texture& texture, int spriteWidth, int spriteHeight) 
        : texture(texture), spriteWidth(spriteWidth), spriteHeight(spriteHeight) {}

    sf::Sprite getSprite(int index) {
        int x = index % (texture.getSize().x / spriteWidth) * spriteWidth;
        int y = index / (texture.getSize().x / spriteWidth) * spriteHeight;

        sf::Sprite sprite;
        sprite.setTexture(texture);
        sprite.setTextureRect(sf::IntRect(x, y, spriteWidth, spriteHeight));
        return sprite;
    }

private:
    sf::Texture& texture;
    int spriteWidth;
    int spriteHeight;
};
```

This class takes in:

- A sf::Texture which is the sprite sheet image
- The width and height of each sprite

It then allows you to call getSprite(index) and pass in an index, and it will return an sf::Sprite object with the correct portion of the texture set as its texture rect, to display that individual sprite from the sheet.

