1. Define the sequence lock data structure and the lock/unlock functions:
```c
struct sequence_lock {
    pthread_mutex_t mutex;
    pthread_cond_t condition;
    int count;
    int seq_number;
};

void lock_sequence(struct sequence_lock *sl) {
    pthread_mutex_lock(&sl->mutex);
    while (sl->seq_number != sl->count++) {
        pthread_cond_wait(&sl->condition, &sl->mutex);
    }
}

void unlock_sequence(struct sequence_lock *sl) {
    pthread_mutex_unlock(&sl->mutex);
    pthread_cond_signal(&sl->condition);
}
```
1. Implement a simple thread function that demonstrates the usage of the sequence lock:
```c
void *sequence_thread(void *arg) {
    struct sequence_lock *sl = (struct sequence_lock *)arg;
    int my_seq_number = 0;

    lock_sequence(sl);
    printf("Thread %ld acquired lock with seq_number %d\n", (long)pthread_self(), my_seq_number);
    usleep(1000);
    unlock_sequence(sl);
    printf("Thread %ld released lock\n", (long)pthread_self());

    return NULL;
}
```
