Here is an example of how to create a resizeable array in Rust:
```rust
use std::vec::Vec;

// Define a struct for the type of element stored in the array
struct MyType {
    value: i32,
}

// Define a new struct that wraps a vec and provides a resize method
struct ResizeableArray {
    values: Vec<MyType>,
}

impl ResizeableArray {
    fn new() -> Self {
        ResizeableArray { values: Vec::new() }
    }

    fn resize(&mut self, new_size: usize) {
        let old_size = self.values.len();
        self.values.resize(new_size);
        for i in 0..(old_size - new_size) {
            self.values.pop().unwrap();
        }
    }
}

fn main() {
    let arr = ResizeableArray::new();
    arr.resize(5);
    arr.push(MyType { value: 1 });
    arr.push(MyType { value: 2 });
    arr.push(MyType { value: 3 });
    println!("{:?}", arr.values); // [MyType { value: 1 }, MyType { value: 2 }, MyType { value: 3 }]
}
