```c
#include <iostream>
#include <fstream>
#include <Windows.h>

int main() {
    ifstream file("text.txt");
    if (!file) {
        std::cerr << "Unable to open file" << std::endl;
        return 1;
    }

    std::string text;
    file.getline(text, '\n');

    HWND hwnd = GetForegroundWindow();
    if (hwnd == 0) {
        std::cerr << "Unable to get foreground window" << std::endl;
        return 1;
    }

    SendMessage(hwnd, WM_COPY, 0, reinterpret_cast<LPARAM>(text.c_str()));

    file.close();
    return 0;
}
```
