        // Smoothly interpolate towards the target position
        transform.position = Vector3.Lerp(transform.position, targetPosition, smoothness * elapsedTimeSinceLastUpdate);

        // Update the last time we updated the position
        lastUpdateTime = Time.time;

        // If we are not currently delaying the update, set the delay flag to true
