#include <stdbool.h>

int main() {
    int sum = 0;
    int i;

    for (i = 2; i <= 1000; i++) {
        if (is_prime(i)) {
            sum += i;
        }
    }

    printf("The sum of all primes from 1 to 1000 is: %d\n", sum);

    return 0;
}

bool is_prime(int n) {
    if (n <= 1) {
        return false;
    }

    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}
