```javascript
function betterCompression(S) {
  // Create an object to count the frequency of each character
  let charCount = {};
  for (let i = 0; i < S.length; i++) {
    let count = S[i].toString().length;
    let char = S[i];
    if (charCount[char]) {
      charCount[char] += count;
    } else {
      charCount[char] = count;
    }
  }

  // Create a new string with the compressed characters and their counts
  let result = "";
  for (let charIndex = 0; charIndex < charCount.length; charIndex++) {
    if (charCount[charIndex] > 1) {
      result += charIndex + ":" + charCount[charIndex] + " ";
    } else {
      result += charCount[charIndex] + " ";
    }
  }
  result += "0";

  // Replace the spaces in the result with commas
  result = result.replace(/ /g, ",");

  // Return the compressed string
  return result;
}
```
