<summary>
    A função Clerp calcula a posição de um ângulo em um arco de círculo.
</summary>

<param name="start">
    O ângulo inicial do arco de círculo.
</param>

<param name="end">
    O ângulo final do arco de círculo.
</param>

<param name="value">
    Um valor entre 0 e 1 que especifica a posição do ângulo no arco de círculo.
</param>

<returns>
    A posição do ângulo no arco de círculo.
</returns>

public static float Clerp(float start, float end, float value)
{
    float min = 0.0f;
    float NAME_1 = 360.0f;
    float half = Mathf.Abs((NAME_1 - min) / 2.0f); //half the distance between min and NAME_1
    float retval = 0.0f;
    float diff = 0.0f;

    if ((end - start) < -half)
    {
        diff = ((NAME_1 - start) + end) * value;
        retval = start + diff;
    }
    else if ((end - start) > half)
    {
        diff = -((NAME_1 - end) + start) * value;
        retval = start + diff;
    }
    else
        retval = start + (end - start) * value;

    return retval;
}
