#include <iostream>
#include <opencv2/opencv.hpp>

int main() {
    // Charger la vidéo
    std::string video_filename = "video.mp4";
    cv::VideoCapture video_capture(video_filename);

    // Vérifier que la vidéo a été chargée avec succès
    if (!video_capture.isOpened()) {
        std::cerr << "Erreur lors du chargement de la vidéo " << video_filename << std::endl;
        return 1;
    }

    // Démarrer la vidéo
    if (video_capture.read(1) != 3) {
        std::cerr << "Erreur lors de la lecture de la vidéo " << video_filename << std::endl;
        return 1;
    }

    // Créer une fenêtre pour afficher la vidéo
    cv::namedWindow("Vidéo", cv::WINDOW_NORMAL);

    // Boucle de mise à jour de la fenêtre
    while (video_capture.isOpened()) {
        // Lire une image de la vidéo
        std::vector<cv::Mat> frames;
        std::vector<cv::KeyPoint> keypoints;
        cv::VideoCapture::read(video_capture, frames, keypoints);

        // Afficher l'image de la vidéo dans la fenêtre
