```csharp
using UnityEngine;
using UnityEngine.UI;

public class ScrollableUI : MonoBehaviour
{
    public Transform content;
    public Transform scrollView;
    public float itemHeight;
    public float scrollSpeed = 5f;
    public int numItems = 10;

    private int currentItem = 0;

    void Update()
    {
        // Calculate the total height of the content
        float contentHeight = content.localScale.y * itemHeight;

        // Calculate the current item position
        float itemPosition = currentItem * contentHeight;

        // Calculate the scroll view position
        float scrollViewPosition = scrollView.localScale.y * contentHeight;

        // Scroll the content if the scroll view position has changed
        if (scrollViewPosition != lastScrollViewPosition)
        {
            if (scrollViewPosition > lastScrollViewPosition)
            {
                // Scrolling up
                content.Translate(Vector3.down * (scrollViewPosition - lastScrollViewPosition) * scrollSpeed);
            }
            else if (scrollViewPosition < lastScrollViewPosition)
            {
                // Scrolling down
                content.Translate(Vector3.up * (lastScrollViewPosition - scrollViewPosition) * scrollSpeed);
            }

            lastScrollViewPosition = scrollViewPosition;
        }

        // Update the current item position
        currentItem = Mathf.RoundToInt(itemPosition / itemHeight);
    }
}
