Here is an example of a thread pool implementation in C++ that is thread-safe:

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

std::vector<std::thread*> thread_pool;

class ThreadPool {
public:
    ThreadPool(size_t num_threads) {
        for (size_t i = 0; i < num_threads; i++) {
            thread_pool.emplace_back(nullptr);
        }
    }

    ~ThreadPool() {
        for (auto& thread : thread_pool) {
            if (thread!= nullptr) {
                thread->join();
            }
        }
    }

    void enqueue(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        cv.wait(lock, [this] { return stop ||!tasks.empty(); });
        tasks.push(task);
    }

    void stop() {
        cv.notify_all(lock);
    }

    void join() {
        cv.wait(lock, [this] { return stop ||!tasks.empty(); });
    }

    void run() {
        while (!stop) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(queue_mutex);
                if (tasks.empty()) {
                    cv.wait(lock, [this] { return!stop; });
                    continue;
                }
                task = tasks.front();
                tasks.pop();
            }
            thread_pool[next_thread_id]->join();
            next_thread_id = (next_thread_id + 1) % num_threads;
            thread_pool[next_thread_id] = new std::thread(task);
        }
    }

private:
    std::vector<std::thread*> thread_pool;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;

