    "fmt"
    "time"
)

func sum(slice []int, ch chan int) {
    sum := 0
    for _, v := range slice {
        sum += v
    }
    ch <- sum
}

func main() {
    slice := []int{1, 2, 3, 4, 5}

    ch := make(chan int)
    go sum(slice[1:], ch)
    go sum(slice[:1], ch)

    result1 := <-ch
    result2 := <-ch

    fmt.Println(result1, result2)
    // Output: 6 6
}
```
