    void Start()
    {
        CreateHexagons();
    }

    void CreateHexagons()
    {
        hexagons = new GameObject[gridSize * numHexagons];

        for (int x = 0; x < gridSize; x++)
        {
            for (int y = 0; y < numHexagons; y++)
            {
                float height = Random.Range(0f, heightScale * 2f);
                GameObject hexagon = new GameObject();
                hexagon.transform.position = new Vector3(x, 0, y);
