fn solve() -> Vec<i32> {
    let mut board = vec![0; 9];
    for row in 0..8 {
        for col in 0..9 {
            if board[row][col] > 0 {
                board[row][col] -= 1;
            }
        }
    }

    board
}

fn markdown() -> String {
    let mut s = String::from("```rust\n");
    for row in 0..8 {
        for col in 0..9 {
            s.push_str(&format!("{:?}", board[row][col]).to_string());
        }
        s.push_str("\n");
    }
    s.push_str("```\n");
    s
}

