private void UploadAllReportsToS3(DataTable dataTable, string s3ConsolidatedReportFolderPath, ExcelOperations excelOperations)
{
    // Get the original report folder path from the data table.
    string s3OriginalFolderPath = "";
    int rowNumber = 2;
    foreach (var reportPath in BankStatementFilePathsSet.GetInstance.StatementFilePaths.DownloadedReportsPath)
    {
        if (!string.IsNullOrEmpty(dataTable.Rows[rowNumber - 2][StringConstants.OriginalReportS3PathCol].ToString()))
        {
            s3OriginalFolderPath = dataTable.Rows[rowNumber - 2][StringConstants.OriginalReportS3PathCol].ToString();
        }
        else
        {
            s3OriginalFolderPath = dataTable.Rows[0][StringConstants.OriginalReportS3PathCol].ToString();
        }

        // Check if the folder path is valid.
        if (System.IO.Directory.Exists(s3OriginalFolderPath))
        {
            // Upload the report to S3.
            UploadReportToS3(dataTable, s3ConsolidatedReportFolderPath, s3OriginalFolderPath, excelOperations);
        }

        // Increment the row number and move to the next report path.
        rowNumber++;
    }
}
