  // Find all the users in the database
  const users = pool.query('SELECT * FROM users');

  // Create a new user
  const newUser = {
    name: req.body.name,
    email: req.body.email,
    password: req.body.password,
    role: 'user',
  };

  users.insert(newUser).then(() => {
