app.post('/login', (req, res) => {
  // Find the user with the specified email and password
  const user = {
    email: req.body.email,
    password: req.body.password,
  };

  // Check if the user is already in the database
  const hasUser = users.find(user).length > 0;

  if (hasUser) {
    // If the user is already in the database, just return their data
    res.send(user);
  } else {
    // If the user is not in the database, create a new user and log them in
    const newUser = {
      name: req.body.name,
      email: req.body.email,
      password: req.body.password,
      role: 'user',
    };

    users.insert(newUser).then(() => {
