/// <summary>
/// Calcula o vector resultado de interpolar entre dois vetores baseados em um valor interpólado.
/// </summary>
/// <param name="start">O vetor de origem.</param>
/// <param name="end">O vetor de destino.</param>
/// <param name="value">O valor interpólado entre 0 e 1.</param>
/// <returns>O vector resultado da interpolação.</returns>
public static Vector3 Sinerp(Vector3 start, Vector3 end, float value)
{
    return new Vector3(start.x + (end.x - start.x) * value, 
        start.y + (end.y - start.y) * value, 
        start.z + (end.z - start.z) * value);
}
