A generic repository is a template that can be used to create a reusable and flexible code storage solution. Here is an example of how to write a generic repository in C#:

1. Define the interface: Create an interface that defines the basic CRUD (Create, Read, Update, Delete) operations for your repository.
```csharp
public interface IRepository<TEntity> where TEntity : class
{
    TEntity GetById(int id);
    void Add(TEntity entity);
    void Update(TEntity entity);
    void Delete(TEntity entity);
}
```
2. Implement the generic repository: Create a generic repository class that implements the interface defined in step 1.
```csharp
public class Repository<TEntity> : IRepository<TEntity> where TEntity : class
{
    private readonly DbContext _context;
    private readonly DbSet<TEntity> _entities;

    public Repository(DbContext context)
    {
        _context = context;
        _entities = context.Set<TEntity>();
    }

    public TEntity GetById(int id)
    {
        return _entities.Find(id);
    }

    public void Add(TEntity entity)
    {
        _entities.Add(entity);
        _context.SaveChanges();
    }

    public void Update(TEntity entity)
    {
        _context.Entry(entity).State = EntityState.Modified;
        _context.SaveChanges();
    }

    public void Delete(TEntity entity)
    {
        _entities.Remove(entity);
        _context.SaveChanges();
    }
}
```
3. Use the repository: Create a concrete repository class that inherit from the generic repository and specify the type parameter.
```csharp
public class AccountRepository : Repository<Account>
{
    public AccountRepository(DbContext context) : base(context)
    {
    }
}
```
4. Register the repository: Register the concrete repository in the IoC container for it to be used in the application.
```csharp
var services = new ServiceCollection();
services.AddTransient<IRepository<Account>, AccountRepository

>>();
services.AddTransient<IUnitOfWork>(provider => provider.GetService<DbContext>());
```
5. Use the repository: Inject the repository into the class that needs to use it and use it to perform the CRUD operations.
```csharp
public class AccountController : Controller
{
    private readonly IRepository<Account> _accountRepository;

    public AccountController(IRepository<Account> accountRepository)
    {
        _accountRepository = accountRepository;
    }

    [HttpGet("{id}")]
    public Account Get(int id)
    {
        return _accountRepository.GetById(id);
    }

    [HttpPost]
    public void Add(Account account)
    {
        _accountRepository.Add(account);
    }

    [HttpPut("{id}")]
    public void Update(int id, Account account)
    {
        _accountRepository.Update(account);
    }

    [HttpDelete("{id}")]
    public void Delete(int id)
    {
        _accountRepository.Delete(id);
    }
}
```
This is a basic example of how to create a generic repository in C#, the actual implementation may vary depending on your specific requirements and the ORM you are using.

