const jwt = require('jsonwebtoken');
const { User } = require('./user'); // You should import your User model here

// Middleware to verify the JWT token
const authenticateJWT = async (req, res, next) => {
  try {
    const token = req.headers.authorization.split(' ')[1];
    if (!token) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const decoded = jwt.verify(token, 'your_secret_key'); // Replace 'your_secret_key' with your own secret key

    // Validate the decoded payload
    const { exp, sub } = decoded;

    if (exp < Date.now()) {
      return res.status(401).json({ error: 'Token expired' });
    }

    if (User.findByPk(sub)) {
      return next();
    }

    return res.status(401).json({ error: 'Unauthorized' });
  } catch (err) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
};

