The time complexity of sorting a singly linked list using selection sort is O(n^2), as it iterates through the list twice to perform the sort. Here's a C++ implementation of selection sort for a singly linked list:
```cpp
#include <iostream>

struct Node {
    int data;
    Node* next;
};

Node* createNode(int data) {
    Node* newNode = new Node;
    newNode->data = data;
    newNode->next = nullptr;
    return newNode;
}

Node* selectionSort(Node* head) {
    if (!head || !head->next) return head;

    Node* smallest = head;
    Node* current = head->next;

    while (current) {
        if (current->data < smallest->data) {
            smallest = current;
        }
        current = current->next;
    }

    smallest->next = head->next;
    head->next = smallest;

    return selectionSort(head->next);
}

int main() {
    Node* head = createNode(1);
    Node* node1 = createNode(4);
    Node* node2 = createNode(5);
    Node* node3 = createNode(6);
    Node* node4 = createNode(7);

    head->next = node1;
    node1->next = node2;
    node2->next = node3;
    node3->next = node4;

    head = selectionSort(head);

    while (head) {
        std::cout << head->data << " -> ";
        head = head->next;
    }

    std::cout << "NULL\n";

    return 0;
}
```
In this implementation, the `selectionSort` function takes a pointer to the head of the singly linked list and recursively sorts the list in-place. The function finds the smallest node in the current section of the list and swaps it with the head of the section. It then continues to sort the remaining section of the list. The time complexity of the selection sort algorithm is O(n^2), where n is the number of nodes in the list.

