```kotlin
import java.util.Arrays

fun quickSort(array: Array<String>): Array<String> {
    if (array.isEmpty()) {
        return array
    }

    val pivot = array[0] // or use an `index` or `min` function to select the pivot
    val left = array.filter { it!== pivot }
    val right = array.filter { it === pivot }

    return quickSort(left).andThen(quickSort(right))
}
```
