fn load_file_into_cache(cache: &FileCache, file_path: &Path) -> Result<Vec<File>, std::io::Error> {
    let file = File::new(file_path)?;
    let mut files: Vec<File> = Vec::new();
    files.push(file);
    Ok(files)
