Here's a basic Chrome extension that can track updates to a div on a page:

```js
// manifest.json
{
  "manifest_version": 2,
  "name": "Content Tracker",
  "permissions": ["activeTab"],
  "background": {
    "scripts": ["background.js"]
  }
}

// background.js
let targetDiv;

chrome.runtime.onInstalled.addListener(() => {
  chrome.tabs.query({active: true, currentWindow: true}, tabs => {
    chrome.tabs.sendMessage(tabs[0].id, {message: "getTargetDiv"});
  });
});

chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.message === "setTargetDiv") {
    targetDiv = request.div;
  }
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === "complete" && targetDiv) {
    chrome.tabs.sendMessage(tabId, {
      message: "checkForUpdates",
      div: targetDiv
    });
  }
});

// content.js
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.message === "getTargetDiv") {
    let div = document.querySelector("#some-div");
    chrome.runtime.sendMessage({message: "setTargetDiv", div});
  } else if (request.message === "checkForUpdates") {
    let div = document.querySelector(request.div);
    if (div.textContent !== lastText) {
      lastText = div.textContent;
      chrome.runtime.sendMessage({message: "divUpdated", text: lastText});
    }
  }
});
```

