            // Read PNG data from the request body
            imgData, err := ioutil.ReadAll(r.Body)
            if err != nil {
                log.Println(err)
                return
            }

            // Decode the PNG image
            var img image/png.Image
            err = png.Decode(bytes.NewBuffer(imgData))
            if err != nil {
                log.Println(err)
                return
            }

            // Render the image in a window
