      const distance = Math.sqrt(dx ** 2 + dy ** 2);
      const force = calculateRepulsionForce(particles[i], particles[j]);
      particles[i].x += force / particles.length;
      particles[i].y += force / particles.length;
      particles[j].x -= force / particles.length;
      particles[j].y -= force / particles.length;
    }
  }
}
