```c++
#include <iostream>
#include <vector>

using namespace std;

void quicksort(vector<int> &arr, int low, int high) {
    if (low < high) {
        int pivot = partition(arr, low, high);
        quicksort(arr, low, pivot - 1);
        quicksort(arr, pivot + 1, high);
    }
}

int partition(vector<int> &arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return i + 1;
}

int main() {
    vector<int> arr = {5, 4, 3, 2, 1};
    quicksort(arr, 0, arr.size() - 1);
    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}
```
This implementation uses the "in-place" partitioning scheme, which does not require extra space. The pivot element is chosen as the last element in the array, but it could be any element. The partition function moves all elements smaller than the pivot to the left of the pivot and all elements greater than the pivot to the right. The pivot is then placed at the end of the smaller partition. The pivot element is not swapped, so it remains in its original position.

The quicksort function is then called recursively on the left and right partitions, and the base case is when the low index is greater than the high index, which means there is only one element in the array. The final result is that the elements in the array are sorted in ascending order, and the output is:
