#include <driver/adc.h>
#include <driver/dma.h>

#define ADC_CHANNEL_0  ADC1_CHANNEL_0  // GPIO36
#define ADC_CHANNEL_1  ADC1_CHANNEL_1  // GPIO37
#define DMA_ADC_CHANNEL 1 

int adc_reading_0;
int adc_reading_1;

void setup() {
  Serial.begin(115200);

  // Enable ADC
  adc1_config_width(ADC_WIDTH_12Bit);
  adc1_config_channel_atten(ADC_CHANNEL_0, ADC_ATTEN_0db);
  adc1_config_channel_atten(ADC_CHANNEL_1, ADC_ATTEN_0db);

  // Enable DMA
  dma_channel_config(DMA_ADC_CHANNEL, DMA_PERIPH_ADC, DMA_PERIPH_MEM);
  dma_set_dest_size(DMA_ADC_CHANNEL, 4, DMA_SIZE_32BITS);
  dma_set_src_size(DMA_ADC_CHANNEL, 4, DMA_SIZE_32BITS);

  // Start conversion and DMA transaction
  adc_start_convert(ADC_CHANNEL_0, ADC_CHANNEL_1);
  dma_start(DMA_ADC_CHANNEL, (uint32_t)&ADC1.adc_out[ADC_CHANNEL_0], (uint32_t)&adc_reading_0, 2, DMA_OPTION_NONE);

  // Wait for conversion to finish
  while (adc_get_convert_status(ADC_CHANNEL_0) != ADC_CONVERT_FINISHED) {} 
}

void loop() {
  Serial.print("Channel 0: ");
  Serial.print(adc_reading_0);
  Serial.print("  Channel 1: ");
  Serial.println(adc_reading_1);
}
