- Configures ADC channels 0 and 1 
- Enables DMA on channel 1 
- Starts an ADC conversion on channels 0 and 1
- Starts a DMA transfer to transfer the conversion results to adc_reading_0 and adc_reading

Here is an example code for ESP32 to use SPI communication with another ESP32:
```scss
#include <SPI.h>

const int spiHostRxPin = 10;
const int spiHostTxPin = 9;
const int spiGuestRxPin = 11;
const int spiGuestTxPin = 12;

void setup() {
  Serial.begin(115200);
  SPI.begin();
  pinMode(spiHostRxPin, INPUT);
  pinMode(spiHostTxPin, OUTPUT);
  pinMode(spiGuestRxPin, INPUT);
  pinMode(spiGuestTxPin, OUTPUT);
}

void loop() {
  // Transmit data on SPI guest channel
  digitalWrite(spiGuestTxPin, HIGH);
  SPI.transfer(spiGuestTxPin >> 4); // MSB of 8-bit data
  SPI.transfer(spiGuestTxPin & 0xF); // LSB of 8-bit data
  digitalWrite(spiGuestTxPin, LOW);

  // Receive data on SPI host channel
  SPI.transfer(spiHostRxPin >> 4); // MSB of 8-bit data
  SPI.transfer(spiHostTxPin & 0xF); // LSB of 8-bit data

  // Print received data
  Serial.print("Received data: ");
  Serial.println(spiGuestTxPin >> 4);
  Serial.print("  ");
  Serial.println(spiGuestTxPin & 0xF);

  delay(100);
}
```
