```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

void read_image(const string& filename, vector<vector<char>>& image) {
    ifstream file(filename);
    string line;
    int x, y;

    if (file.is_open()) {
        while (getline(file, line)) {
            istringstream line_stream(line);
            string token;
            while (getline(line_stream, token, ' ') || token != "") {
                x = stoi(token);
                if (file.peek() == EOF) break;
                getline(file, token);
                y = stoi(token);
                image[x][y] = file.peek() != EOF;
            }
        }
        file.close();
    } else {
        cout << "Error: Could not open the image file." << endl;
    }
}

