Here's an example implementation of quick sort in C++:
```c++
#include <iostream>
#include <vector>

using namespace std;

void quick_sort(vector<int> &arr, int low, int high) {
    if (low < high) {
        int pivot = partition(arr, low, high);
        quick_sort(arr, low, pivot - 1);
        quick_sort(arr, pivot + 1, high);
    }
}

int partition(vector<int> &arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j <= high - 1; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return i + 1;
}

int main() {
    vector<int> arr = {4, 6, 2, 1, 5, 3};
    quick_sort(arr, 0, arr.size() - 1);
    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}
```
This implementation uses a recursive approach to partition the input array into two sub-arrays around a pivot element, and then recursively sorts the left and right sub-arrays using the quick sort algorithm. The pivot element is chosen as the last element in the array, but it could be any element. The partition function uses a "burying the hatchet" strategy to maintain the heap property of the array while partitioning it.

