```c++
#include <iostream>
#include <string>

using namespace std;

int main() {
    string statement;
    cout << "Enter a statement: ";
    getline(cin, statement);

    // Truth table:
    int n = 2; // number of variables
    vector<vector<int>> truthTable(n, vector<int>(n, 0));

    // Evaluate the statement using the truth table
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (statement[i] == '0') {
                truthTable[i][j] = 1 - truthTable[i][j];
            } else if (statement[i] == '1') {
                truthTable[i][j] = truthTable[i][j];
            }
        }
    }

    // Check if the statement is logically equivalent or not
    bool isEquivalent = true;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (truthTable[i][j] != 0) {
                if (i == j) {
                    truthTable[i][j] = 1;
                } else {
                    truthTable[i][j] = 0;
                    isEquivalent = false;
                    break;
                }
            }
        }
    }

    if (isEquivalent) {
        cout << "The statement is logically equivalent." << endl;
    } else {
        cout << "The statement is not logically equivalent." << endl;
    }

    return 0;
}
```
