func quicksort(list sorted_list) sorted_list {
    if len(list) <= 1 {
        return list
    }

    pivot := list[len(list)/2]
    left := []sorted_item{item: pivot.item, value: pivot.value}
    middle := []sorted_item{}
    right := []sorted_item{item: pivot.item, value: pivot.value}

    for len(list) > 1 {
        for len(middle) > 0 {
            if list[len(list)-1].item.compare(middle[len(middle)-1].item) <= 0 {
                middle = middle[:len(middle)-1]
                continue
            }
            list = append(list, middle[len(middle)-1])
            middle = middle[:len(middle)-1]
        }

        for len(left) > 0 && len(right) > 0 {
            if left[len(left)-1].item.compare(right[len(right)-1].item) <= 0 {
                left = left[:len(left)-1]
                continue
            }
            list = append(list, right[len(right)-1])
            right = right[:len(right)-1]
        }

        if len(left) > 0 {
            list = append(list, left[len(left)-1])
        }
        if len(right) > 0 {
            list = append(list, right[len(right)-1])
        }
    }

    return list
}
