#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

// Define a struct to store the timestamps of each wakelock request
struct Timestamp {
    int ts;
    Timestamp() { ts = 0; }
    Timestamp(int t) { ts = t; }
};

// Define a class to represent an application's wakelock usage
class Application {
public:
    Application(vector<Timestamp> t) { ts = t[0]; }
    void request() { ts = t[1]; }
    void release() { t[1] = ts; }
    double getContribution() { return (ts - t[0]) / (t[1] - t[0]); }

private:
    vector<Timestamp> t;
};

int main() {
