```csharp
/// <summary>
/// Realiza uma interpolação de Hermite entre dois pontos
/// </summary>
/// <param name="start">Ponto de partida</param>
/// <param name="end">Ponto de destino</param>
/// <param name="value">Valor da interpolação</param>
/// <returns>Ponto de interpolação</returns>
public static Vector3 Hermite(Vector3 start, Vector3 end, float value)
{
    float squared = value * value;
    float cubed = squared * squared;
    float result = (cubed / 64.0f) * (cubed / 64.0f) * (cubed / 64.0f);
    result = start.x + (end.x - start.x) * value * result + (squared * result * result * result);
    result = start.y + (end.y - start.y) * value * result + (squared * result * result * result);
    result = start.z + (end.z - start.z) * value * result + (squared * result * result * result);
    return new Vector3(result);
}
```
