    public float moveDistance = 5.0f; // distance to move the camera
    public float cameraHeight = 1.5f; // height of the camera

    private GameObject player; // reference to the player object

    void Start()
    {
        // get the player object
        player = gameObject.GetComponent<Player>();

        // set the camera position
        player.transform.localScale = new Vector3(cameraHeight, moveDistance, cameraHeight);

        // set the camera rotation
        player.transform.rotation = Quaternion.Euler(0, 0, -moveDistance * Time.deltaTime);
    }

    void Update()
    {
        // move the camera
        Vector3 move = player.transform.forward;

        // move the camera to the new position
        move = Vector3.ClampMagnitude(move, cameraHeight) - cameraHeight;

        // set the new camera position
        player.transform.localScale = new Vector3(0.5f, 0.5f, 0.5f) * move;

        // play the animation
        gameObject.SetActive(false);
        gameObject.GetComponent<Animator>().play("CameraMove");
    }
}
