    sort(edges.begin(), edges.end());
    priority_queue<Edge, vector<Edge>, greater<Edge>> pq;
    vector<Edge> mst;
    int n = edges.size();
    for (int i = 0; i < n; i++) {
        Edge e = edges[i];
        if (pq.empty() || e.weight < pq.top().weight) {
            pq.push(e);
        } else {
            mst.push_back(e);
            pq.pop();
        }
    }
