```javascript
function sortArray(arr) {
  // First, we sort the array in descending order of string length
  arr.sort((a, b) => b.length - a.length);

  // Next, we return an object containing the longest element, the shortest element, and the sorted array
  const longest = arr[0];
  const shortest = arr[0];
  const sorted = arr.slice(); // Make a copy of the sorted array

  // Find the longest and shortest elements in the sorted array
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i].length > longest.length) {
      longest = sorted[i];
    }
    if (sorted[i].length < shortest.length) {
      shortest = sorted[i];
    }
  }

  // Return an object containing the longest and shortest elements and the sorted array
  return { longest, shortest, sorted };
}
```

