public static Dictionary<string, List<MyClass>> GetDictionaryByYear(List<MyClass> myClassList) {
    var result = new Dictionary<string, List<MyClass>>();
    var dateToKey = DateTimeOffset.MinValue;
    foreach (var item in myClassList) {
        if (item.MyDate.HasValue && item.MyDate.Value > dateToKey) {
            result.Add(item.MyDate.Value.ToString("yyyy"), new List<MyClass> { item });
            dateToKey = item.MyDate.Value + TimeSpan.FromDays(1);
        } else if (item.MyDate.HasValue && item.MyDate.Value == dateToKey) {
            result[item.MyDate.Value.ToString("yyyy")].Add(item);
        }
    }
    result.OrderBy(x => x.Key);
    return result;
}
