public class Cell {
    public int X { get; set; }
    public int Y { get; set; }
    public string Name { get; set; }

    public event CellEventHandler ValueChanged;

    public Cell(int x, int y, string name) {
        X = x;
        Y = y;
        Name = name;
    }
}

public class QuadTree {
    private readonly List<Cell> cells = new List<Cell>();
    private readonly int divisions;

    public QuadTree(int divisions) {
        this.divisions = divisions;
    }

    public void AddCell(Cell cell) {
        cells.Add(cell);
    }

    public void RemoveCell(Cell cell) {
        cells.Remove(cell);
    }

    public IEnumerable<Cell> GetCells() {
        return cells;
    }

    public void IterateCells(Action<Cell> action) {
        foreach (var cell in cells) {
            action(cell);
            if (cell.X < divisions || cell.Y < divisions) {
                Divide();
            }
        }
    }

    private void Divide() {
        var midX = divisions / 2;
        var midY = divisions / 2;

        var topLeft = new Cell(midX, midY, "top-left");
        var topRight = new Cell(midX + 1, midY, "top-right");
        var bottomLeft = new Cell(midX, midY + 1, "bottom-left");
        var bottomRight = new Cell(midX + 1, midY + 1, "bottom-right");

        cells.AddRange(topLeft, topRight);
        cells.AddRange(bottomLeft, bottomRight);
    }
}
