Here's the complete Rust code:
```rust
pub fn diagonal_sum(mat: Vec<Vec<i32>>) -> i32 {
    let m = mat.len() as i32; // get the number of rows and columns as i32
    let mut sum_diag1 = 0;
    let mut sum_diag2 = 0;

    for i in 0..m {
        sum_diag1 += mat[i][i] as i32; // sum the elements on the primary diagonal
        sum_diag2 += mat[i][m - i - 1] as i32; // sum the elements on the secondary diagonal
    }

    sum_diag1 + sum_diag2 as i32
}
