```cpp
#include <iostream>

class NAME_1 {
public:
    int data;
    NAME_1* next;
};

class Stack {
public:
    Stack() : top(nullptr) {}

    void push(int value) {
        NAME_1* newNode = new NAME_1();
        newNode->data = value;
        newNode->next = top;
        top = newNode;
    }

    int pop() {
        if (isEmpty()) {
            std::cout << "Stack is empty. Cannot pop.\n";
            return -1;
        }
        int poppedValue = top->data;
        NAME_1* tempNode = top;
        top = top->next;
        delete tempNode;
        return poppedValue;
    }

    int peek() {
        if (isEmpty()) {
            std::cout << "Stack is empty. Cannot peek.\n";
            return -1;
        }
        return top->data;
    }

    bool isEmpty() {
        return top == nullptr;
    }

private:
    NAME_1* top;
};

int main() {
    Stack stack;

    stack.push(10);
    stack.push(20);
    stack.push(30);

    std::cout << "Top element is: " << stack.peek() << std::endl;
    std::cout << "Popped element: " << stack.pop() << std::endl;
    std::cout << "Top element is: " << stack.peek() << std::endl;

    return 0;
}
```

