    int data;
    NAME_1* next;
};

class Queue {
public:
    Queue() : front(nullptr), rear(nullptr) {}

    void enqueue(int value) {
        NAME_1* newNode = new NAME_1();
        newNode->data = value;
        newNode->next = nullptr;

        if (isEmpty()) {
            front = rear = newNode;
        } else {
            rear->next = newNode;
            rear = newNode;
        }
