برنامه زیر یک عبارت میانوندی را دریافت می‌کند، آن را به عبارت پسوندی تبدیل می‌کند و در نهایت مقدار عبارت پسوندی را ارزیابی می‌کند. برای سادگی، فرض می‌کنیم که عبارت میانوندی فقط شامل اعداد یک رقمی و عملگرهای +،-،* و / باشد.

```cpp
#include <iostream>
#include <stack>
#include <string>

int precedence(char op) {
    if (op == '+' || op == '-')
        return 1;
    if (op == '*' || op == '/')
        return 2;
    return 0;
}

std::string infixToPostfix(const std::string& infix) {
    std::stack<char> operators;
    std::string postfix;

    for (char ch : infix) {
        if (isdigit(ch)) {
            postfix.push_back(ch);
        } else {
            while (!operators.empty() && precedence(operators.top()) >= precedence(ch)) {
                postfix.push_back(operators.top());
                operators.pop();
            }
            operators.push(ch);
        }
    }

    while (!operators.empty()) {
        postfix.push_back(operators.top());
        operators.pop();
    }

    return postfix;
}

int evaluatePostfix(const std::string& postfix) {
    std::stack<int> operands;

    for (char ch : postfix) {
        if (isdigit(ch)) {
            operands.push(ch - '0');
        } else {
            int second = operands.top();
            operands.pop();
            int first = operands.top();
            operands.pop();
            int result;

            switch (ch) {
                case '+': result = first + second; break;
                case '-': result = first - second; break;
                case '*': result = first * second; break;
                case '/': result = first / second; break;
            }
            operands.push(result);
        }
    }

    return operands.top();
}

int main() {
    std::string infix;
    std::cout << "Enter an infix expression: ";
    std::cin >> infix;

    std::string postfix = infixToPostfix(infix);
    std::cout << "Postfix expression: " << postfix << std::endl;

    int result = evaluatePostfix(postfix);
    std::cout << "Result: " << result << std::endl;

    return 0;
}
```

این برنامه از دو تابع کمکی استفاده می‌کند: `infixToPostfix` برای تبدیل عبارت میانوندی به پسوندی و `evaluatePostfix` برای ارزیابی عبارت پسوندی. در تابع `main`، عبارت میانوندی ورودی دریافت شده، به عبارت پسوندی تبدیل می‌شود و سپس مقدار آن ارزیابی می‌شود.

