class Button {
  constructor() {
    this.onClick = [];
  }

  addOnClick(func) {
    this.onClick.push(func);
  }

  onClick() {
    this.onClick.forEach(func => func());
  }
}

class Receiver {
  constructor() {
    this.on = [];
  }

  addOn(func) {
    this.on.push(func);
  }

  on() {
    this.on.forEach(func => func());
  }
}

