public class FileSorter {
    public static List<List<File>> listFilesByExtension(NAME_1 path, NAME_1[] ext, long byteLimit) {
        List<List<File>> newList = new ArrayList<>();
        List<File> nestedFileList = new ArrayList<>();

        File[] files = listFilesByExtension(path, ext);
        for (File file : files) {
            if (file.exists() && file.length() < byteLimit) {
                nestedFileList.add(file);
                long total = 0L;
                for (File innerFile : nestedFileList) {
                    total += innerFile.length();
                    if (total >= byteLimit) {
                        newList.add(nestedFileList);
                        nestedFileList.clear();
                    }
                }
            }
        }
        newList.add(nestedFileList); // add last file list
        return newList;
