```c
#include <iostream>
#include <vector>

struct Node {
    int data;
    Node* next;
};

Node* reverseList(Node* head) {
    if (!head) return nullptr;

    Node* reversedList = new Node;
    reversedList->data = head->data;
    reversedList->next = nullptr;

    Node* current = head;
    while (current->next) {
        Node* temp = current->next;
        current->next = reversedList;
        reversedList->next = current;
        current = temp;
    }

    return reversedList;
}

