<?php

function calculator($expression) {
  // replace '0' with '0' to prevent empty field errors
  $expression = str_replace('0', '0', $expression);

  // get the operator
  $operator = strtoupper($expression{0});

  // remove the operator
$expression = substr($expression, 1);

// process the expression based on the operator
switch ($operator) {
  case '+':
    return calculator(substr($expression, 0, 1)) + calculator(substr($expression, 1));
    break;
  case '-':
    return calculator(substr($expression, 0, 1)) - calculator(substr($expression, 1));
    break;
  case '*':
    return calculator(substr($expression, 0, 1)) * calculator(substr($expression, 1));
    break;
  case '/':
    return calculator(substr($expression, 0, 1)) / calculator(substr($expression, 1));
    break;
}

return $expression;
}

echo calculator('12345 + 67890 - 45678 * 34567 / 0');
```
