    return new Vector3(Sinerp(start.x, end.x, value), Sinerp(start.y, end.y, value), Sinerp(start.z, end.z, value));
}

/// <summary>
/// Realiza o cálculo da função sinerp para dois vetores 3D.
/// </summary>
/// <param name="x1">O valor do primeiro vector.</param>
/// <param name="x2">O valor do segundo vector.</param>
/// <param name="y1">O valor do primeiro vector.</param>
/// <param name="y2">O valor do segundo vector.</param>
/// <param name="z1">O valor do primeiro vector.</param>
/// <param name="z2">O valor do segundo vector.</param>
/// <returns>A função sinerp interpolada.</returns>
private static float Sinerp(float x1, float x2, float y1, float y2, float z1, float z2, float t)
{
    float x = x1 + (x2 - x1) * t;
    float y = y1 + (y2 - y1) * t * t;
    float z = z1 + (z2 - z1) * t * t * t;
    return (float)Math.Sin(t * Math.PI / 2) * Math.Sqrt(x * x + y * y + z * z);
}

