As an experienced ASP.NET Web API developer, I would use bearer authentication to authenticate both API key clients and JWT clients by implementing a custom authentication middleware that supports both types of authentication.

Here are the steps I would follow:

1. Define the authentication schemes: First, I would define the authentication schemes that I want to support. For this example, I will support both API keys and JWT tokens.
2. Implement the authentication middleware: I would implement a custom authentication middleware that can check the authentication header of the incoming request and authenticate the user based on the authentication scheme.

Here is an example of how the middleware would look like:
```csharp
public class BearerAuthMiddleware
{
    private readonly RequestDelegate _next;

    public BearerAuthMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Get the authentication header from the incoming request
        string authHeader = context.Request.Headers["Authorization"];

        // Check if the authentication header is valid
        if (authHeader == null)
        {
            context.Response.StatusCode = 401;
            return;
        }

        // Check if the authentication scheme is supported
        if (authHeader.StartsWith("Bearer "))
        {
            // API key authentication
            string apiKey = authHeader.Substring(7);
            if (apiKey != "my-api-key")
            {
                context.Response.StatusCode = 401;
                return;
            }
        }
        else if (authHeader.StartsWith("Bearer"))
        {
            // JWT token authentication
            string token = authHeader.Substring("Bearer ".Length);
            var handler = new JwtSecurityTokenHandler();
            var jwtToken = handler.ReadJwtToken(token);
            if (jwtToken == null)
            {
                context.Response.StatusCode = 401;
                return;
            }
        }

        // Authentication succeeded, continue with the next middleware
        await _next(context);
    }
}
