function sortArray(arr) {
  // First, we sort the array in descending order of string length
  arr.sort((a, b) => b.length - a.length);

  // Next, we extract the longest and shortest elements from the sorted array
  const longest = arr[0];
  const shortest = arr[0];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i].length > longest.length) {
      longest = arr[i];
    }
    if (arr[i].length < shortest.length) {
      shortest = arr[i];
    }
  }

  // Finally, we return an object that contains the longest element, the shortest element,
  // and the sorted array
  return {
    longest: longest,
    shortest: shortest,
    sorted: arr
  };
}
