```c
#include <iostream>
#include <string>

using namespace std;

void reverseString(string str)
{
    int left = 0, right = str.length() - 1;
    while (left < right)
    {
        char temp = str[left];
        str[left] = str[right];
        str[right] = temp;
        left++;
        right--;
    }
}

int main()
{
    string str = "hello world";
    reverseString(str);
    cout << str << endl;
    return 0;
}
```
