A linked list is a data structure that consists of a sequence of elements, each containing a reference to the next element in the sequence. Here's an example of creating a simple singly linked list using C:

```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a single NAME_1 in the list
typedef struct NAME_1 {
    int data;             // The data in the NAME_1
    struct NAME_1 *next;    // Pointer to the next NAME_1 in the list
} NAME_1;

// Function to create a new NAME_1
NAME_1 *newNode(int data) {
    NAME_1 *NAME_1 = (NAME_1 *)malloc(sizeof(NAME_1));
    NAME_1->data = data;
    NAME_1->next = NULL;
    return NAME_1;
}

// Function to insert a new NAME_1 at the end of the list
void insertEnd(NAME_1 **head, int data) {
    NAME_1 *new_NAME_1 = newNode(data);
    if (*head == NULL) {
        *head = new_NAME_1;
        return;
    }
    NAME_1 *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_NAME_1;
}

// Function to print the list
void printList(NAME_1 *head) {
    NAME_1 *current = head;
    while (current != NULL) {
        printf("%d -> ", current->data);
        current = current->next;
    }
    printf("NULL\n");
}

// Main function to demonstrate the linked list
int main() {
    NAME_1 *head = NULL; // Start with an empty list

    insertEnd(&head, 5);
    insertEnd(&head, 10);
    insertEnd(&head, 15);

    printf("Linked list: ");
    printList(head);

    return 0;
}
```

This program demonstrates how to create a singly linked list with nodes containing integer data. The `newNode` function creates a new NAME_1 with the given data, and the `insertEnd` function inserts a new NAME_1 at the end of the list. The `printList` function is used to print the elements of the list.

