```sql
CREATE OR REPLACE FUNCTION last_5_digits_and_period(input_string VARCHAR)
RETURNS INTEGER AS $$
DECLARE
  input_int INTEGER;
BEGIN
  -- Try to cast the input string to an integer
  input_int := CAST(input_string AS INTEGER);

  -- If the cast fails, return null
  IF input_int IS NULL THEN
    RETURN NULL;
  END IF;

  -- If the input string is all digits, return the last 5 characters as an integer
  IF input_string REGEXP '[0-9]+' THEN
    RETURN input_string::INTEGER % 1000000;
  END IF;

  -- If the input string is not all digits, return null
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;
```
