function generatePrompt() {
  // Select the word div element
  const wordDiv = document.querySelector("#word");

  // Remove all child nodes from the word div element
  while (wordDiv.firstChild) {
    wordDiv.removeChild(wordDiv.firstChild);
  }

  // Use the words in the roomsArray to populate the word div element with new words
  for (let i = 0; i < roomsArray.length; i++) {
    const room = roomsArray[i];
    const word = document.createElement("div");
    word.classList.add("word");
    word.innerText = room.description;
    wordDiv.appendChild(word);

    // Add a button to the word div element for each possible exit from the room
    for (const exit of room.exits) {
      const exitButton = document.createElement("button");
      exitButton.innerText = `Go ${exit}`;
      exitButton.style.backgroundColor = "lightblue";
      exitButton.style.borderRadius = "5px";
      exitButton.style.padding = "5px 10px";
      exitButton.style.marginRight = "5px";
      wordDiv.appendChild(exitButton);

      // Add an event listener to the exit button
      exitButton.addEventListener("click", () => {
        // Move the player to the next room
        player.room = roomsArray.indexOf(exit);

        // Toggle the player's inventory items
        player.inventory.forEach((item) => {
          item.visible =!item.visible;
        });

        // Update the player's location in the game
        player.update(room.description);
      });

      // Add a closed sign to the exit button if the player cannot go that way
      if (roomsArray.indexOf(exit) === -1) {
        exitButton.innerText = "Closed";
        exitButton.style.backgroundColor = "red";
      }
    }
  }

  // Select the word div element
  const wordDiv = document.querySelector("#word");

  // Determine which word is currently visible
  const currentWord = wordDiv.childNodes.length > 0? wordDiv.childNodes[0].innerText : "";

  // Update the prompt element with the current word
  promptElement.innerText = currentWord;
}

