    std::string current_consumer_id;
    std::string current_producer_id;

public:
    SinglePublisherMultipleConsumerQueue() {
        current_consumer_id = "";
        current_producer_id = "";
    }

    void enqueue(const std::string& message) {
        if (!queue.size()) {
            queue.push(message);
        } else {
            std::string current_message = queue.front();
            queue.pop();
            if (current_message == message) {
                return;
            }
            queue.push(message);
        }
    }

    std::string consume(std::string& consumer_id) {
        if (queue.size() == 0) {
            return "";
        }
        std::string message = queue.front();
        queue.pop();
        if (message == current_producer_id) {
            current_producer_id = "";
            current_consumer_id = consumer_id;
            return message;
        }
        return "";
    }

