elif defined(posix):
  const libName = "libmylib.so"

proc doSomething*() {.importc: libName, header: "mylib.h".}
proc add*(a, b: int): int {.importc: libName, header: "mylib.h".} 
```

5. Import and call the C++ library from Nim code:

```nim 
