Using an array to store the products in the cart is a simple and effective way to implement the cart functionality. When the user adds a product to the cart, you can create a new object in the array to represent the product and add it to the cart array.

Here's an example of how you could implement the cart functionality using an array:
```javascript
// Define an array to store the products in the cart
let cart = [];

// Define a function to handle the "add to cart" button click
function addToCart(product) {
  // Create a new object to represent the product in the cart
  let cartItem = {
    name: product.name,
    price: product.price,
    quantity: 1
  };

  // Push the cart item to the cart array
  cart.push(cartItem);

  // Update the UI to show the updated cart
  displayCart();
}

// Define a function to display the cart
function displayCart() {
  // Get the element to display the cart
  let cartDisplay = document.getElementById("cart-display");

  // Clear the previous cart items
  cartDisplay.innerHTML = "";

  // Loop through the cart items and display them
  for (let i = 0; i < cart.length; i++) {
    let cartItem = cart[i];
    let itemDisplay = document.createElement("div");

    itemDisplay.innerHTML = `
      <p>${cartItem.name}</p>
      <p>${cartItem.price} x ${cartItem.quantity}</p>
      <button onclick="removeFromCart(i)">Remove</button>
    `;

    cartDisplay.appendChild(itemDisplay);
  }
}

// Define a function to handle the "remove from cart" button click
