To solve this problem, we can use a depth-first search (DFS) algorithm to traverse the graph and mark all the vertices that we visit as visited. Then, we can check if there is a path between any two remaining vertices that have not been visited. If there is, then we add the unvisited vertices to the current connected component and continue the DFS. If there is no path between any two remaining vertices, then we have found a complete connected component and we can return its size.

Here is the C++ code that implements this algorithm:
```cpp
int numCompleteComponents(int n, vector<vector<int>>& edges) {
    vector<bool> visited(n, false);
    queue<pair<int, int>> q;
    q.push(make_pair(0, 0));
    visited[0] = true;

    while (!q.empty()) {
        pair<int, int> cur = q.front();
        q.pop();
        int v = cur.first;

        // check all edges connected to vertex v
        for (int w : edges[v]) {
            if (!visited[w]) {
                // mark vertex w as visited
                visited[w] = true;
                q.push(make_pair(w, v));
            }
        }
    }

    int count = 0;
    // traverse the visited vertices and count the complete components
    for (int i = 0; i < n; i++) {
        if (visited[i]) {
            int j = i;
            while (j < n && visited[j]) {
                j = edges[j][0];
            }
            if (j == i) {
                count++;
            }
        }
    }

    return count;
}
```
The time complexity of this algorithm is O(n^2), where n is the number of vertices in the graph, since we traverse every edge in the graph and we visit every vertex twice - once when we mark it as visited and again when we count the complete components. The space complexity is O(n), since we store the visited states of vertices in a vector.

