```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

struct Point {
    double north;
    double east;
    double elevation;
};

std::vector<Point> load_csv(const std::string& file_path) {
    std::vector<Point> points;
    std::ifstream file(file_path);

    if (!file.is_open()) {
        std::cerr << "Error: Could not open file: " << file_path << std::endl;
        return points;
    }

    std::string line;
    std::getline(file, line); // Read and discard header line

    while (std::getline(file, line)) {
        std::stringstream ss(line);
        std::string cell;

        Point point;
        if (std::getline(ss, cell, ',')) {
            point.north = std::stod(cell);
        }
        if (std::getline(ss, cell, ',')) {
            point.east = std::stod(cell);
        }
        if (std::getline(ss, cell, ',')) {
            point.elevation = std::stod(cell);
        }
        points.push_back(point);
    }

    file.close();
    return points;
}

int main() {
    std::string file_path = "data.csv";
    std::vector<Point> points = load_csv(file_path);

    for (const Point& point : points) {
        std::cout << "North: " << point.north
                  << ", East: " << point.east
                  << ", Elevation: " << point.elevation << std::endl;
    }

    return 0;
}
```

This code defines a `Point` struct to store the north, east, and elevation values. The `load_csv` function reads the CSV file and populates a vector of `Point` structs. In the `main` function, the CSV file is loaded, and the contents are printed to the console.

