```csharp
public class CacheDecorator<TInput, TOutput>
{
    private readonly Func<TInput, TOutput> func;
    private readonly object lockObject = new object();
    private readonly Dictionary<TInput, TOutput> cache;

    public CacheDecorator(Func<TInput, TOutput> func)
    {
        this.func = func;
        this.cache = new Dictionary<TInput, TOutput>();
    }

    public TOutput GetValue(TInput input)
    {
        lock (lockObject)
        {
            if (cache.ContainsKey(input))
            {
                return cache[input];
            }

            TOutput output = func(input);
            cache.Add(input, output);
            return output;
        }
    }
}
```
