    /// Remove a scale transformation from a matrix
    /// </summary>
    /// <param name="Mat">The matrix to apply the transformation to</param>
    /// <returns>The modified matrix without the scale transformation</returns>
    public static Matrix4 RemoveScale(ref Matrix4x4 Mat)
    {
        Vector3 scale = GetScale(Mat);

        if (scale.x != 0.0f)
        {
            float invX = 1.0f / scale.x;

            Mat.m00 *= invX;
            Mat.m10 *= invX;
            Mat.m20 *= invX;
