function selectTimeZone(timeZone) {
  // Look up the time zone offset for the selected time zone
  // For example, EST is -5 hours behind GMT
  switch (timeZone) {
    case 'UTC':
      timeZoneOffset = 0;
      break;
    case 'EST':
      timeZoneOffset = -5 * 60;
