public static HashSet<string> GetDependencyBreakColumnsToNull(
    Table table,
    IEnumerable<ColumnRelationship> relationships,
    IReadOnlySet<TableDependencyBreak> dependencyBreaks)
{
    if (!TonicEnvironmentVariable.TONIC_SUBSETTING_AGGRESSIVELY_NULL_CYCLICAL_FKS.Get<bool>())
    {
        return new HashSet<string>();
    }

    var targetBreaks = dependencyBreaks
        .Where(db => db.ForeignKeyTable.Schema == table.SchemaOfTable && db.ForeignKeyTable.Table == table.TableName)
        .Select(db => db.PrimaryKeyTable)
        .ToHashSet();

    var relatedTargetBreaks = relationships
        .Where(r => r.Nullable && r.FkEquals(table) && targetBreaks.Contains(r.PkSchemaAndTable))
        .Select(r => r.PkSchemaAndTable)
        .ToHashSet();

    return relationships
        .Where(r => r.Nullable && r.FkEquals(table) && relatedTargetBreaks.Contains(r.PkSchemaAndTable) &&
                    table.Columns.Any(x => x.ColumnName == r.FkColumn && x.IsNullable))
        .Select(r => r.FkColumn)
        .ToHashSet();
}
