app.post('/api/users', (req, res) => {
  const { name, email } = req.body;
  const newUser = { name, email };
  User.create({ name, email }, newUser).then((user) => {
    res.send(`User created: ${user.name} ${user.email}`);
  }).catch((err) => {
    res.send(`Error creating user: ${err}`);
  });
});

// Read
app.get('/api/users', (req, res) => {
  const users = User.query().then((users) => {
    res.json(users);
  });
});

// Update
app.put('/api/users/:id', (req, res) => {
  const { id } = req.params;
  const user = User.find(id);
  if (!user) {
    res.status(404).send('User not found');
  } else {
    user.name = req.body.name;
    user.email = req.body.email;
    user.save().then((user) => {
      res.send(`User updated: ${user.name} ${user.email}`);
    }).catch((err) => {
      res.send(`Error updating user: ${err}`);
    });
  }
});

// Delete
app.delete('/api/users/:id', (req, res) => {
  const { id } = req.params;
  User.query().then((users) => {
    const user = users.find(id);
    if (user) {
      User.destroy(user);
      res.send(`User deleted: ${user.name} ${user.email}`);
    } else {
      res.status(404).send('User not found');
    }
  }).catch((err) => {
    res.send(`Error deleting user: ${err}`);
  });
});

const port = process.env.PORT || 3000;
