template <typename T>
class GpuOffloadContext {
    static GpuOffloadContext* instance() {
        static GpuOffloadContext s_ctx;
        return &s_ctx;
    }

    GpuOffloadContext() : m_wait_state(true), m_popped(false) {}

    ~GpuOffloadContext() {
        m_wait_state = false;
        m_popped = true;
        std::for_each(m_data.begin(), m_data.end(), [](T* ptr) {
            delete ptr;
        });
    }

    GpuOffloadContext(bool wait_state) : m_wait_state(wait_state), m_popped(false) {}
    GpuOffloadContext(const GpuOffloadContext&) = delete;
    GpuOffloadContext& operator=(const GpuOffloadContext&) = delete;

    void push(T* ptr) {
        if (m_popped) {
            m_popped = false;
            std::atomic::store(&m_wait_state, true, std::memory_order_relaxed);
        }
        m_data.push_back(ptr);
    }

    T pop() {
        if (m_wait_state) {
            return m_data.front();
        }
        if (m_popped) {
            m_popped = true;
            std::atomic::store(&m_wait_state, false, std::memory_order_relaxed);
        }
        return m_data.front();
    }

private:
    GpuOffloadContext s_ctx;
    std::atomic<bool> m_wait_state;
    std::vector<T*> m_data;
    bool m_popped;
};

