Here is a Node.js server with endpoints for signup and login, using MariaDB for storage:

```js
const express = require('express')
const mariadb = require('mariadb')

const app = express()
app.use(express.json())

// MariaDB connection
const conn = mariadb.createConnection({
  host: 'localhost',
  user: 'user',
  password: 'password',
  database: 'my_db' 
})

// Signup endpoint
app.post('/signup', (req, res) => {
  const name = req.body.name
  const email = req.body.email
  const password = req.body.password

  conn.query(
    'INSERT INTO users (name, email, password) VALUES (?, ?, ?)', 
    [name, email, password],
    (err, results) => {
      if (err) throw err
      res.send('User created!')
    }
  )
})

// Login endpoint 
app.post('/login', (req, res) => {
  const email = req.body.email
  const password = req.body.password

  conn.query(
    'SELECT * FROM users WHERE email = ? AND password = ?',
    [email, password],
    (err, results) => {
      if (err) throw err
      if (results.length > 0) {
        res.send('Login succeeded!')  
      } else {
        res.send('Invalid email or password')  
      }
    }
  )
})

app.listen(3000)
```

This server:

- Connects to a MariaDB database 
- Has /signup and /login endpoints
- /signup inserts a new user into the `users` table
- /login checks if a user with the given email and password exists, and returns a success/failure message
- Listens on port 3000

