You can use the SharePoint REST API to list files in a document library with JavaScript. Here's an example code snippet:


```javascript
using SharePoint = Microsoft.SharePointOnline.Claims;
using Microsoft.SharePoint.Linq;
using Microsoft.SharePoint.List;
using Microsoft.SharePoint.Web;
using Microsoft.Rest;
using System.Net.Http;

var client = new SharePointOnlineClient(SharePoint.Online, clientSecret);

var list = client.Sites.FirstOrDefault(s => s.Lists.FirstOrDefault(l => l.Title == "Documents"));

if (list != null)
{
    var camlQuery = new CamlQuery();
    camlQuery.ViewXml = "<View><Query><Where><Eq><FieldRef Name='FileLeafRef' /><Operator>eq</Operator><Values><FileRef>*"</FileRef></Values></Eq></Where></Query></View>";

    var files = list.GetItems(camlQuery).ToList();
    foreach (var file in files)
    {
        Console.WriteLine(file.FileRef);
    }
}

```

Note: Replace `` SharePoint.Online `` with `` SharePoint.Online.Claims `` to use the claims-based authentication. Replace `` clientSecret `` with your actual client secret.

