private Canvas canvas;
private Paint paint;
private float x, y, x1, y1, x2, y2;

public void select(float x, float y) {
    // Save the initial pixel coordinates
    x1 = x;
    y1 = y;
    x2 = x;
    y2 = y;

    // Draw a rectangle around the initial selection
    paint.setColor(Color.argb(255, 255, 255, 255));
    canvas.drawRect(x - 5, y - 5, x + 10, y + 10, paint);
}

public void drag(float x, float y) {
    // Update the selection coordinates as the user drags
    x = x - x1 - (x2 - x1);
    y = y - y1 - (y2 - y1);

    // Check if the user is dragging outside the initial selection
    if (x < x1 || x > x2 || y < y1 || y > y2) {
        x1 = x;
        y1 = y;
        x2 = x;
        y2 = y;

        // Draw a rectangle around the new selection
        paint.setColor(Color.argb(255, 255, 255, 255));
        canvas.drawRect(x - 5, y - 5, x + 10, y + 10, paint);
    }
}

public void tap(float x, float y) {
    // Check if the user has tapped inside the initial selection
    if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
