      bet.dataValues as Bets & {
        totalUnmatchedLiability: number;
        totalMatchedLiability: number;
      };
    const stmId = selectionIdMap[selectionId];

    accumulator[stmId] = accumulator[stmId] || {};
    accumulator[stmId][odds] = accumulator[stmId][odds] || {
      layBetsMatched: 0,
      layBetsUnmatched: 0,
      backBetsMatched: 0,
      backBetsUnmatched: 0,
    };

    const result = accumulator[stmId][odds];
    const isLay = side === BetSide.Lay;
    const matched = isLay
      ? this.calculateStakeForLayPrice(odds, totalMatchedLiability)
      : totalMatchedLiability;
    const unmatched = isLay
      ? this.calculateStakeForLayPrice(odds, totalUnmatchedLiability)
      : totalUnmatchedLiability;

    if (isLay) {
      result.backBetsMatched = this.plus(matched, result.backBetsMatched);
      result.backBetsUnmatched = this.plus(unmatched, result.backBetsUnmatched);
    } else {
      result.layBetsMatched = this.plus(matched, result.layBetsMatched);
      result.layBetsUnmatched = this.plus(unmatched, result.layBetsUnmatched);
    }
  }
}
