```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.Http;
using Microsoft.AspNet.WebApi.Http;
using Microsoft.Azure.SqlDatabase.SqlTypes;
using Microsoft.Data.Entity;
using Microsoft.Extensions.Http;

namespace MyWebAPI.Controllers
{
    public class FilesController : ApiController
    {
        private readonly MyDbContext _dbContext;

        public FilesController(MyDbContext dbContext)
        {
            _dbContext = dbContext;
        }

        [HttpPost]
        public void Post([Required] MultipartFormDataContent formData)
        {
            foreach (var file in formData.FileMultiparts)
            {
                var filename = file.Headers.ContentDisposition.FileName.Trim('\"');
                var filepath = Path.Combine(Directory.GetCurrentDirectory(), "uploads", filename);
                file.CopyTo(filepath);

                var fileBytes = new byte[filepath.Length];
                using (var stream = new FileStream(filepath, FileMode.Open, FileAccess.Read))
                {
                    stream.Read(fileBytes, 0, (int)stream.Length);
                }

                var fileBlob = new SqlAzureBinary(fileBytes);
                var fileId = Guid.NewGuid();
                _dbContext.Files.Add(new File
                {
                    FileName = filename,
                    FileType = GetFileType(filepath),
                    FileSize = file.ContentLength,
                    FileData = fileBlob,
                    FileId = fileId
                });
                _dbContext.SaveChanges();
            }
        }

        private string GetFileType(string filepath)
        {
            var fileExtension = Path.GetExtension(filepath);
            switch (fileExtension)
            {
                case ".pdf":
                    return "PDF";
                case ".jpg":
                case ".jpeg":
                    return "Image";
                case ".docx":
                case ".doc":
                    return "Word Document";
                case ".xlsx":
                case ".xls":
                    return "Excel Document";
                default:
                    return "Other";
            }
        }
    }
}
```
In this example, we define an endpoint with the HTTP POST method, which expects a MultipartFormDataContent object in the request body. This object contains the file(s) to be uploaded.

We then loop through each file in the MultipartFormDataContent object and save the file to disk using the Path.Combine method to create a unique file path in a directory called "uploads". We then read the contents of the file into a byte array and persist it to the database as a SqlAzureBinary object. We also add a new Guid to the database to uniquely identify the file.

Note that this example assumes that you are using Entity Framework to interact with your database, and that you have already set up a DbContext and a File entity class with the necessary properties to store the file data. You may need to modify this code to fit your specific needs and database schema.

