function delete sheets() {
  // Get the active spreadsheet
  var spreadsheet = SpreadsheetApp.getActiveSpreadsheet();

  // Get the range of the first sheet
  var firstSheet = spreadsheet.getSheetByName("Sheet1");

  // Get the range of the sheets to be deleted
  var toDelete = spreadsheet.getSheetNames();
  var deleteSheetNames = toDelete.split(",");

  // Remove the first sheet from the list of sheets to be deleted
  deleteSheetNames.splice(deleteSheetNames.indexOf(firstSheet), 1);

  // Get the new list of sheets to be deleted
  var newSheetNames = deleteSheetNames.join(",");

  // Delete the new list of sheets
  spreadsheet.getSheetNames(newSheetNames);
}
