#include <iostream>
#include <queue>
using namespace std;

class Grid {
    public:
        Grid(int row, int col) : row(row), col(col) {}
        int get(int row, int col) { return grid[row][col]; }
        int get(int row) { return row; }
        int get(int col) { return col; }

    private:
        int row, col;
        int grid[5][5];
    };

class AStar {
    public:
        AStar(int row, int col) : grid(row, col) {}
        Grid findPath() {
            queue<Grid> q;
            q.push(Grid(row, col));

            while (!q.empty()) {
                Grid curr = q.front();
                q.pop();

                for (int i = 0; i < 4; i++) {
                    for (int j = 0; j < 4; j++) {
                        if (curr.get(i, j) == 0) {
                            int newRow = i + 1;
                            int newCol = j + 1;
                            if (newRow >= 0 && newRow < 5 && newCol >= 0 && newCol < 5) {
                                Grid newGrid = Grid(newRow, newCol);
                                if (newGrid.get(i, j) == 0) {
                                    q.push(newGrid);
                                }
                            }
                        }
                    }
                }
            }

            return Grid(row, col, 0);
        }

    private:
        Grid grid;
};

