func NewJetDB() (*sql.DB, error) {
	db, err := sql.Open("jet", "sqlite3::memory:")
	if err != nil {
		return nil, err
	}
	return db, nil
}

func main() {
	db, err := NewJetDB()
	if err != nil {
		fmt.Println(err)
		return
	}
	defer db.Close()

	// Select all columns from a table
	rows, err := db.Query("SELECT * FROM users")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer rows.Close()

	for rows.Next() {
		var id int
		var name string
		if err := rows.Scan(&id, &name); err != nil {
			fmt.Println(err)
			return
		}
		fmt.Printf("id: %d, name: %s\n", id, name)
	}
}
```
