// markdown-to-html.pipe.ts
import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name:'markdownToHtml'
})
export class MarkdownToHtmlPipe implements PipeTransform {
  transform(value: string, markup: string): string {
    const regex = /(^<([a-z][a-z0-9]*)\b[^>]*>(.*?)<\/\1>)/g;
    const tag = regex.exec(value);
    let html = '';
    if (tag!= null) {
      const { tagName, attrs } = tag[0];
      const attrList = attrs.split(' ');
      attrList.forEach(attr => {
        if (attr === 'class') {
          html += `class="${attr}"";`;
        } else if (attr ==='style') {
          html += `style="${attr}"";`;
        } else if (attr!== null) {
          html += `${attr}="${attr}"";`;
        }
      });
      html += `<${tagName} ${attrList.join(' ')}>`;
      html += tag[2];
      html += '</${tagName}>';
    } else {
      html = value;
    }
    return html;
  }
}

