    .owner = THIS_MODULE,
    .write = gpio_toggle,
    .unlocked_ioctl = gpio_toggle,
};

static struct miscdevice gpio_miscdev = {
    .minor = MISC_DYNAMIC_MINOR,
    .name = "gpio_toggle",
    .fops = &gpio_fops,
};

static int __init gpio_init(void)
{
    int ret;

    ret = misc_register(&gpio_miscdev);
    if (ret < 0) {
        printk(KERNEL_ERR "gpio_init: Failed to register misc device\n");
        return ret;
    }

    printk(KERNEL_INFO "GPIO toggle device registered as /dev/gpio_toggle\n");

    return 0;
}

static void __exit gpio_exit(void)
{
    misc_deregister(&gpio_miscdev);
    printk(KERNEL_INFO "GPIO toggle device unregistered\n");
}

