Here's an implementation of `dlist_copy()` function in C that creates a deep copy of the input `list`, where each element of the list is copied:
```c
#include <stdlib.h>

struct dlist *dlist_copy(const struct dlist *list) {
    struct dlist *new_list = malloc(sizeof(struct dlist));
    if (new_list == NULL) {
        return NULL;
    }

    new_list->head = malloc(sizeof(struct dlist_node) * (list->size + 1));
    if (new_list->head == NULL) {
        free(new_list);
        return NULL;
    }

    new_list->tail = new_list->head;
    new_list->size = 0;

    struct dlist_node *current = list->head;
    while (current != NULL) {
        struct dlist_node *new_node = malloc(sizeof(struct dlist_node));
        if (new_node == NULL) {
            free(new_list->head);
            free(new_list);
            return NULL;
        }

        // Copy the data of the node
        new_node->data = current->data;

        // Copy the next pointer
        new_node->next = current->next;

        // Update the tail of the new list
        if (new_list->tail == current) {
            new_list->tail = new_node;
        }

        new_list->size++;
        current = current->next;
    }

    return new_list;
}
```
This function takes a pointer to an existing `dlist` as its input, `list`, and returns a pointer to a new `dlist` that is a deep copy of `list`. The function first allocates memory for the new list and its nodes, and then iterates over each node in the original list, copying the data of each node and updating the next pointer to point to the next node in the new list. Finally, the function returns the new list. If any memory allocation fails, the function returns `NULL`.

