#include <iostream>
#include <iptunnel.h>

int main() {
  // Create a tun interface
  iptunnel::TunnelInterface tun_if = iptunnel::TunnelInterface::new();
  tun_if.set_local_address(192, 168, 1, 1);
  tun_if.set_remote_address(192, 168, 1, 2);
  tun_if.set_protocol(iptunnel::TunnelInterface::Protocol::TUNNEL);
  tun_if.set_link(iptunnel::TunnelInterface::Link::TUNNEL);

  // Add the tun interface to the system
  tun_if.attach();

  // Remove the tun interface
  tun_if.detach();

  // The tun interface is now removed from the system
  return 0;
}
```
In the example above, we create a tun interface with a local address of 192.168.1.1 and a remote address of 192.168.1.2, and set the protocol to `TUNNEL` and the link to `TUNNEL`. We then attach the tun interface to the system, and finally detach it to remove it.

